<template>
  <SiteNav />
  <HeroSection />
  <ResearchSection />
  <PublicationsSection />
  <TeachingSection />
  <CvSection />
  <ContactSection />
  <SiteFooter />
</template>

<script>
import SiteNav from './components/SiteNav.vue'
import HeroSection from './components/HeroSection.vue'
import ResearchSection from './components/ResearchSection.vue'
import PublicationsSection from './components/PublicationsSection.vue'
import TeachingSection from './components/TeachingSection.vue'
import CvSection from './components/CvSection.vue'
import ContactSection from './components/ContactSection.vue'
import SiteFooter from './components/SiteFooter.vue'

export default {
  name: 'App',
  components: {
    SiteNav, HeroSection, ResearchSection, PublicationsSection,
    TeachingSection, CvSection, ContactSection, SiteFooter,
  },
  mounted() {
    document.title = 'Junlin Li — Academic Profile'
    // Global scroll-reveal observer
    const observer = new IntersectionObserver(entries => {
      entries.forEach(e => {
        if (e.isIntersecting) {
          const siblings = [...e.target.parentElement.querySelectorAll('.reveal')]
          const idx = siblings.indexOf(e.target)
          setTimeout(() => e.target.classList.add('visible'), idx * 60)
          observer.unobserve(e.target)
        }
      })
    }, { threshold: 0.1 })

    this.$nextTick(() => {
      document.querySelectorAll('.reveal').forEach(el => observer.observe(el))
    })
  },
}
</script>
